<?php defined('PREVENT_DIRECT_ACCESS') OR exit('No direct script access allowed'); $labels = ['motel_name' => 'Motel name', 'motel_address' => 'Address', 'motel_lat' => 'Map latitude', 'motel_lng' => 'Map longitude', 'booking_fee' => 'Online booking fee (₱)', 'hold_minutes' => 'Room hold while paying (minutes)', 'cancel_hours' => 'Free cancellation until (hours before check-in)', 'overnight_start' => 'Overnight check-in (HH:MM)', 'overnight_end' => 'Overnight check-out (HH:MM)']; ?>
<h1>Settings</h1>
<div class="grid" style="grid-template-columns:1fr 1fr;align-items:start"><div class="card"><h3>Motel &amp; booking rules</h3><form method="post" action="<?= e(site_url('admin/settings')) ?>"><?= csrf_input() ?>
<?php foreach ($keys as $k): ?><div class="field"><label for="<?= e($k) ?>"><?= e($labels[$k]) ?></label><input id="<?= e($k) ?>" name="<?= e($k) ?>" required maxlength="150" value="<?= e(setting($k)) ?>"></div><?php endforeach; ?><button class="btn btn-block" type="submit">Save settings</button></form></div>
<div class="card"><h3>The five integrations</h3><p class="mute small">Secret keys are set on the server (Render → Environment) and are never shown on this page.</p>
<?php foreach ($integrations as $i => [$name, $on, $note]): ?><div class="row between" style="padding:12px 0;border-top:1px solid var(--glass)"><div><b><?= ($i + 1) . ' · ' . e($name) ?></b><div class="small mute"><?= e($note) ?></div></div><span class="pill <?= $on ? 'ok' : 'warn' ?>"><?= $on ? 'Connected' : 'Not connected' ?></span></div><?php endforeach; ?>
  <h4 style="margin-top:18px">Send a test</h4><p class="mute small">Use these to check your SMS and email keys. A test message uses credits at the provider.</p>
  <?php if (env_get('SMS_PROVIDER') === 'semaphore'): ?><form method="post" action="<?= e(site_url('admin/settings/test-sms')) ?>" class="row" style="margin-bottom:10px"><?= csrf_input() ?><input name="mobile" placeholder="09XX XXX XXXX" maxlength="20" required style="flex:1" aria-label="Mobile number for the SMS test"><button class="btn btn-ink btn-sm" type="submit">Send test SMS</button></form><?php endif; ?>
  <form method="post" action="<?= e(site_url('admin/settings/test-email')) ?>" class="row"><?= csrf_input() ?><input name="email" type="email" placeholder="you@example.com" maxlength="150" required style="flex:1" aria-label="Email address for the email test"><button class="btn btn-ink btn-sm" type="submit">Send test email</button></form></div></div>
